changetheworld.text:
def changeTheWorld():
 while True:
 # 随机选择一张 hdr 贴图
 wd = random.choice(bpy.data.images)
 if wd.name.endswith('hdr'):
 break
 # 将其设置为环境纹理贴图
 bpy.context.scene.world.node_tree.nodes['Environment Texture'].image = wd

