def changeObjs():
 # 遍历场景中的所有物体，将它们从当前激活的 collection 中删除，除了名为 "Camera" 的相机
 for obj in bpy.context.collection.objects:
 if obj.name != 'Camera':
 bpy.context.collection.objects.unlink(obj)
 # 定义一个空列表 nameList
